Algorithm Dado
  Define tirada As Integer;
  Define intentos As Integer <- 0;
  Repeat
    tirada <- random(6) + 1;
    intentos <- intentos + 1;
  Until tirada = 6
  Write "Salió el 6 en el intento ", intentos;
EndAlgorithm

Algorithm UnaVez
  Define n As Integer <- 10;
  Repeat
    Write "Vuelta con n = ", n;
    n <- n + 1;
  Until n > 5
EndAlgorithm

Algorithm RepetirNumero
  Define n As Integer <- 3;
  Repeat
    n <- n - 1;
  Until n
EndAlgorithm
